// Lock + backoff + rate-limit guard + build poll URL
const s = $getWorkflowStaticData('global');
const now = Date.now();
const LOCK_TTL = 90000;

if (s.nextAllowedPoll && now < s.nextAllowedPoll) {
  return [{ json: { canPoll: false, reason: 'backoff', waitMs: s.nextAllowedPoll - now } }];
}
if (s.pollLock && now - s.pollLock < LOCK_TTL) {
  return [{ json: { canPoll: false, reason: 'previous run still active' } }];
}
s.pollTimes = (s.pollTimes || []).filter(t => now - t < 60000);
if (s.pollTimes.length >= 15) {
  return [{ json: { canPoll: false, reason: 'poll rate limit (15/min)' } }];
}
s.pollTimes.push(now);
s.pollLock = now;

// Manual query string construction (No URLSearchParams required)
if (s.startedAt === undefined) s.startedAt = Math.floor(Date.now() / 1000);
const off = (s.offset !== undefined && s.offset !== null && s.offset !== '') ? s.offset : 0;
const queryStr = 'limit=50&timeout=15&offset=' + encodeURIComponent(String(off));

return [{ 
  json: { 
    canPoll: true, 
    pollUrl: 'https://api.whatsapp.com/agent/v1/updates?' + queryStr, 
    offsetUsed: s.offset ?? null 
  } 
}];

// Handle status codes, save offset, dedupe, emit text messages
const s = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const status = Number(r.statusCode ?? r.status ?? 0);
const headers = r.headers || {};
let body = r.body;
if (typeof body === 'string' && body.trim()) { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (!body || typeof body !== 'object') body = {};

function backoff(ms, why) {
  s.failCount = (s.failCount || 0) + 1;
  s.nextAllowedPoll = Date.now() + ms;
  s.lastError = { at: new Date().toISOString(), status, why };
  console.log('[WA-AGENT] poll problem', status, why, 'backoff ms:', ms);
}
const expo = () => Math.min(300000, 5000 * Math.pow(2, Math.min(s.failCount || 0, 6)));

if (status === 200) {
  s.failCount = 0; s.nextAllowedPoll = 0;
} else if (status === 204) {
  s.failCount = 0; s.nextAllowedPoll = 0;
  return [{ json: { hasMessages: false, status } }];
} else if (status === 429) {
  const ra = Number(headers['retry-after'] || headers['Retry-After'] || 0) * 1000;
  backoff(Math.max(60000, ra), 'rate limited');
  return [{ json: { hasMessages: false, status } }];
} else if (status === 409) {
  backoff(30000, 'conflict: another poll active for this agent');
  return [{ json: { hasMessages: false, status } }];
} else if (status === 401 || status === 403) {
  backoff(300000, 'auth/permission error - check WhatsApp Agent token');
  return [{ json: { hasMessages: false, status } }];
} else {
  backoff(expo(), status === 503 ? 'service unavailable' : 'unexpected status/network error');
  return [{ json: { hasMessages: false, status } }];
}

// FIX 1: Offset update from payload OR fallback to highest message ID
if (body.next_offset !== undefined && body.next_offset !== null) {
  s.offset = body.next_offset;
} else if (body.offset !== undefined && body.offset !== null) {
  s.offset = body.offset;
}

// FIX 2: Initialize processedIds and handle first-run bootstrapping
   const isFirstRun = false;
s.processedIds = s.processedIds || [];
const seen = new Set(s.processedIds);

const out = [];
const msgs = [];

for (const e of (Array.isArray(body.entry) ? body.entry : [])) {
  for (const c of (e.changes || [])) {
    for (const m of ((c.value && c.value.messages) || [])) {
      msgs.push(m);
    }
  }
}

// FIX 3: Time filter threshold (e.g., ignore messages older than 3 minutes / 180s)
const NOW_SEC = Math.floor(Date.now() / 1000);
const MAX_AGE_SECONDS = 600;

for (const m of msgs) {
  if (!m || !m.id || !m.from) continue;

  // Deduplication check
  if (seen.has(m.id)) continue;
  seen.add(m.id);
  s.processedIds.push(m.id);

  // If this is the initial run on node restart, seed old IDs and skip execution
  if (isFirstRun) continue;

  // Check timestamp age
  const msgTime = Number(m.timestamp || 0);
  if (msgTime > 0 && (NOW_SEC - msgTime) > MAX_AGE_SECONDS) {
    console.log(`[WA-AGENT] Skipping old message ID: ${m.id}`);
    continue;
  }

  if (m.type !== 'text') continue;
  const text = (m.text && typeof m.text === 'object') ? m.text.body : m.text;
  if (typeof text !== 'string' || !text.trim()) continue;

  out.push({ json: { hasMessages: true, from: String(m.from), messageId: m.id, text } });
}

// Mark first run as completed
s.isInitialized = true;

// Keep sliding window of processed IDs
if (s.processedIds.length > 500) s.processedIds = s.processedIds.slice(-500);

return out.length ? out : [{ json: { hasMessages: false, status } }];

// Log outbound result; back off polling on auth errors
const s = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const status = Number(r.statusCode ?? r.status ?? 0);
if (status >= 200 && status < 300) {
  s.lastSend = { at: new Date().toISOString(), status };
} else {
  s.lastError = { at: new Date().toISOString(), status, why: 'send failed', detail: r.error || r.body || null };
  console.log('[WA-AGENT] send failed', status, JSON.stringify(s.lastError.detail));
  if (status === 401 || status === 403) s.nextAllowedPoll = Date.now() + 300000;
  if (status === 429) s.nextAllowedPoll = Date.now() + 60000;
}
return [{ json: { sendStatus: status } }];

const s = $getWorkflowStaticData('global');
s.pollLock = 0;
return [{ json: { released: true } }];

const s = $getWorkflowStaticData('global');
s.pollLock = 0;
s.lastError = { at: new Date().toISOString(), why: 'workflow error', detail: JSON.stringify($input.first().json).slice(0, 500) };
console.log('[WA-AGENT] workflow error', s.lastError.detail);
return [{ json: { logged: true } }];
